const upgradeDefs=[{id:'magnet',icon:'🧲',name:'Coin charm',desc:'+25% idle coins',base:50},{id:'scout',icon:'🔭',name:'Keen scout',desc:'+5% catch chance',base:70},{id:'power',icon:'💪',name:'Training bell',desc:'+2 team power',base:90}];
const fresh=()=>({coins:0,balls:5,dust:0,party:[],seen:[],caught:0,battles:0,streak:0,bestStreak:0,encounterNo:0,enemy:null,starter:null,upgrades:{magnet:0,scout:0,power:0},dailyClaimed:false,dailyDate:new Date().toDateString(),lastSeen:Date.now(),region:0});
let s;try{s={...fresh(),...JSON.parse(localStorage.getItem('pokeventure-save')||'{}')};if(!Array.isArray(s.party))s.party=[];if(!Array.isArray(s.seen))s.seen=[];s.upgrades={...fresh().upgrades,...s.upgrades};}catch(e){s=fresh()}
let messageTimer=null, toastTimer=null;
const $=id=>document.getElementById(id);const fmt=n=>Math.floor(n).toLocaleString();
function save(){s.lastSeen=Date.now();localStorage.setItem('pokeventure-save',JSON.stringify(s));$('saveText').textContent='Progress saved';}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2100)}
function setMessage(text){$('battleMessage').textContent=text}
function power(){return s.party.reduce((n,p)=>n+p.power+(p.level-1)*2,0)+s.upgrades.power*2}
function coinRate(){return s.party.reduce((n,p)=>n+p.power*.32+(p.level-1)*.12,0)*(1+s.upgrades.magnet*.25)}
function render(){
 $('coins').textContent=fmt(s.coins);$('balls').textContent=fmt(s.balls);$('dust').textContent=fmt(s.dust);$('ballCountBtn').textContent=`(${fmt(s.balls)})`;
 $('teamCount').textContent=s.party.length;$('partyCount').textContent=`${s.party.length} / 6`;$('teamPower').textContent=fmt(power());$('cpm').textContent=fmt(coinRate()*60);$('seenCount').textContent=s.seen.length;$('streak').textContent=s.bestStreak;$('collectionCount').textContent=s.seen.length;
 const reg=regions[Math.min(s.region,regions.length-1)];$('regionName').textContent=reg.name;$('regionArt').textContent=reg.art;$('trailText').textContent=`${Math.max(0,s.battles-reg.unlock)} / ${reg.need}`;$('trailProgress').style.width=`${Math.min(100,Math.max(0,(s.battles-reg.unlock)/reg.need*100))}%`;
 $('encounterNum').textContent=`Trail #${String(s.encounterNo).padStart(3,'0')}`;$('playerName').textContent=s.starter||'Your companion';$('playerLevel').textContent=s.party.length?`Lv. ${Math.max(...s.party.map(p=>p.level))}`:'Lv. 1';$('playerEmoji').textContent=s.party[0]?.emoji||'🥚';$('teamPortrait').textContent=s.party[0]?.emoji||'🌟';$('playerHp').style.width='100%';
 if(s.enemy){$('enemyName').textContent=s.enemy.name;$('enemyLevel').textContent=`Lv. ${s.enemy.level}`;$('enemyEmoji').textContent=s.enemy.emoji;$('enemyHp').style.width=`${Math.max(0,s.enemy.hp/s.enemy.maxHp*100)}%`;$('battleState').textContent='WILD';$('catchBtn').disabled=s.balls<=0;$('attackBtn').disabled=false;$('exploreBtn').disabled=false;}else{$('enemyName').textContent='No wild creature';$('enemyLevel').textContent='—';$('enemyEmoji').textContent=regions[s.region]?.art||'🌱';$('enemyHp').style.width='0%';$('battleState').textContent='READY';$('catchBtn').disabled=true;$('attackBtn').disabled=true;$('exploreBtn').disabled=false;}
 $('partyGrid').innerHTML='';s.party.forEach((p,i)=>{const slot=document.createElement('div');slot.className='party-slot';slot.innerHTML=`<div class="party-emoji" style="background:${p.color}">${p.emoji}</div><div class="party-meta"><div class="party-name">${p.name}</div><div class="party-detail">${p.type} type · Lv. ${p.level}</div><div class="xpbar"><i style="width:${Math.min(100,p.xp%100)}%"></i></div><div class="party-power">Power ${p.power+(p.level-1)*2}</div></div>`;$('partyGrid').appendChild(slot)});for(let i=s.party.length;i<Math.min(6,Math.max(3,s.party.length+1));i++){const el=document.createElement('div');el.className='party-slot empty';el.textContent='＋  Catch a companion';$('partyGrid').appendChild(el)}
 $('boostList').innerHTML='';upgradeDefs.forEach(u=>{const lvl=s.upgrades[u.id],cost=Math.floor(u.base*Math.pow(1.7,lvl));const row=document.createElement('div');row.className='boost-row';row.innerHTML=`<div class="boost-icon">${u.icon}</div><div class="boost-info"><div class="boost-name">${u.name}</div><div class="boost-level">Level ${lvl} · ${u.desc}</div></div><button class="buy-btn" data-up="${u.id}" ${s.coins<cost?'disabled':''}>${fmt(cost)} 🪙</button>`;$('boostList').appendChild(row)});
 $('dailyBtn').disabled=s.dailyClaimed;$('dailyBtn').textContent=s.dailyClaimed?'Done ✓':'Claim';$('dailyDesc').textContent=s.dailyClaimed?'Challenge complete! Come back tomorrow.':`Catch ${Math.max(0,3-s.caught)} more creatures on your journey.`;$('dailyReward').textContent=s.dailyClaimed?'Claimed: 80 coins + 2 orbs':'Reward: 80 coins + 2 orbs';
 $('trailDetail').textContent=`Wild creatures found: ${s.seen.length} · Battles won: ${s.battles} · Catch rate: ${s.battles?Math.round(s.caught/s.battles*100):0}%`;
 $('rank').textContent=`${s.battles<10?'Rookie':s.battles<30?'Trailblazer':s.battles<60?'Ranger':'Elite Trainer'} · Lv. ${1+Math.floor(s.battles/5)}`;
}
function starterModal(){const grid=$('starterGrid');grid.innerHTML='';species.slice(0,3).forEach((p,i)=>{const card=document.createElement('div');card.className='starter';card.innerHTML=`<div class="emoji">${p.emoji}</div><h3>${p.name}</h3><p>${p.type} type · Power ${p.power}</p><button data-starter="${i}">Choose ${p.name}</button>`;grid.appendChild(card)});$('starterModal').classList.add('open')}
function chooseStarter(i){const sp=species[i];s.starter=sp.name;s.party.push({...sp,level:1,xp:0});s.seen.push(sp.name);$('starterModal').classList.remove('open');setMessage(`${sp.name} is ready for an adventure! Explore the grass to meet a wild creature.`);save();render();toast(`${sp.name} joined your party!`)}
function explore(){if(!s.starter){starterModal();return}if(s.enemy){setMessage('A wild creature is already here! Catch it or battle first.');return}const pool=species.filter(x=>!s.seen.includes(x.name)||Math.random()<.28);const sp=pool[Math.floor(Math.random()*pool.length)]||species[Math.floor(Math.random()*species.length)];const lvl=1+Math.min(12,Math.floor(s.battles/6))+Math.floor(Math.random()*2);s.encounterNo++;s.enemy={name:sp.name,emoji:sp.emoji,type:sp.type,power:sp.power,level:lvl,maxHp:20+lvl*8,hp:20+lvl*8,color:sp.color};s.seen=[...new Set([...s.seen,sp.name])];setMessage(`A wild ${sp.name} appeared! Weaken it with a quick attack, or try your luck with an orb.`);render();save()}
function awardBattle(caught=false){if(!s.enemy)return;const foe=s.enemy;s.battles++;s.streak++;s.bestStreak=Math.max(s.bestStreak,s.streak);s.coins+=Math.floor(8+foe.power*2+foe.level*3);s.dust+=Math.max(1,Math.floor(foe.power/3));s.party.forEach(p=>{p.xp+=25+foe.level*3;while(p.xp>=p.level*100){p.xp-=p.level*100;p.level++;p.power++;if(p.name===s.starter)toast(`${p.name} reached level ${p.level}!`)}});s.enemy=null;
 const next=regions.findIndex((r,i)=>i>s.region&&s.battles>=r.unlock+r.need);if(next>=0){s.region=next;showRegion(regions[next])}setMessage(caught?`${foe.name} was caught! Your team earned coins and stardust.`:`${foe.name} fainted! Your team earned coins and stardust.`);render();save()}
function attack(){if(!s.enemy)return;const damage=Math.max(4,Math.floor(power()*.7+2));s.enemy.hp-=damage;if(s.enemy.hp<=0){awardBattle(false);toast('Battle won! Your team found rewards.')}else{setMessage(`Your team dealt ${damage} damage! ${s.enemy.name} has ${Math.ceil(s.enemy.hp)} HP left.`);render()}}
function catchEnemy(){if(!s.enemy||s.balls<=0)return;s.balls--;const chance=Math.min(.93,.22+s.upgrades.scout*.05+(1-s.enemy.hp/s.enemy.maxHp)*.55+power()/(power()+s.enemy.power*5));if(Math.random()<chance){const foe=s.enemy;if(s.party.length<6){s.party.push({name:foe.name,emoji:foe.emoji,type:foe.type,power:foe.power,level:foe.level,xp:0,color:foe.color});toast(`${foe.name} joined your party!`)}else{s.coins+=30;toast('Party full! Released for 30 coins.')}s.caught++;awardBattle(true)}else{setMessage(`Oh no, ${s.enemy.name} broke free! Weaken it and try again.`);if(s.enemy.hp>0)s.enemy.hp=Math.max(1,s.enemy.hp);render();save()}}
function buy(id){const u=upgradeDefs.find(x=>x.id===id);const cost=Math.floor(u.base*Math.pow(1.7,s.upgrades[id]));if(s.coins<cost)return;s.coins-=cost;s.upgrades[id]++;toast(`${u.name} upgraded to level ${s.upgrades[id]}!`);render();save()}
function showRegion(reg){$('regionModalTitle').textContent=`${reg.name} discovered!`;$('regionModalCopy').textContent=`Your journey has taken you to ${reg.name}. New friends and bigger adventures are waiting along this trail.`;$('regionModal').classList.add('open')}
$('exploreBtn').addEventListener('click',explore);$('attackBtn').addEventListener('click',attack);$('catchBtn').addEventListener('click',catchEnemy);$('dailyBtn').addEventListener('click',()=>{if(s.dailyClaimed)return;if(s.caught<3){toast(`Catch ${3-s.caught} more creatures first!`);return}s.dailyClaimed=true;s.coins+=80;s.balls+=2;toast('Challenge complete! +80 coins and 2 orbs.');render();save()});$('regionContinue').addEventListener('click',()=>$('regionModal').classList.remove('open'));$('starterGrid').addEventListener('click',e=>{const b=e.target.closest('[data-starter]');if(b)chooseStarter(+b.dataset.starter)});$('boostList').addEventListener('click',e=>{const b=e.target.closest('[data-up]');if(b)buy(b.dataset.up)});$('allUpgrades').addEventListener('click',e=>{e.preventDefault();document.querySelector('[data-tab="upgrades"]').click()});
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x===b));const tab=b.dataset.tab;if(tab==='collection'){document.querySelector('[data-panel="party"]').click();$('pageTitle').textContent='Creature collection';$('pageSubtitle').textContent=`You've met ${s.seen.length} of ${species.length} creatures so far.`;setMessage(`Seen: ${s.seen.join(', ')||'none yet'}. Keep exploring to complete your collection!`)}else if(tab==='upgrades'){document.querySelector('[data-panel="party"]').click();$('pageTitle').textContent='Train your team';$('pageSubtitle').textContent='Power up your adventure with helpful upgrades.';document.querySelector('.boost-card').scrollIntoView({behavior:'smooth',block:'center'})}else if(tab==='fieldnotes'){document.querySelector('[data-panel="details"]').click();$('pageTitle').textContent='Field notes';$('pageSubtitle').textContent='Everything you have learned on your journey.'}else{$('pageTitle').textContent='The adventure begins!';$('pageSubtitle').textContent='A whole new world is waiting in the tall grass.';document.querySelector('[data-panel="party"]').click()}}));
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));$('panel-party').classList.toggle('hidden',b.dataset.panel!=='party');$('panel-details').classList.toggle('hidden',b.dataset.panel!=='details')}));
if(s.dailyDate!==new Date().toDateString()){s.dailyDate=new Date().toDateString();s.dailyClaimed=false;s.caught=0}
// Restore a modest amount of idle earnings when returning, capped at eight hours.
if(s.starter&&s.lastSeen){const away=Math.min(8*3600,Math.max(0,(Date.now()-s.lastSeen)/1000));const earned=coinRate()*away;if(earned>=1){s.coins+=earned;setMessage(`Welcome back! Your companions earned ${fmt(earned)} coins while you were away.`)}}
render();save();if(!s.starter)starterModal();
setInterval(()=>{if(s.starter){const earned=coinRate()/10;if(earned>0)s.coins+=earned;render();save()}},10000);

